declare_lint_rule! {
    /// Enforce that heading elements (h1, h2, etc.) have content and that the content is accessible to screen readers.
    ///
    /// Accessible means the content is not hidden using the `aria-hidden` attribute.
    /// Headings should have text content that describes the section for screen reader users.
    /// Alternatively, the heading can have an accessible name via the `aria-label` or `title` attribute.
    ///
    /// :::note
    /// In `.html` files, this rule matches element names case-insensitively (e.g., `<H1>`, `<h1>`).
    ///
    /// In component-based frameworks (Vue, Svelte, Astro), only lowercase element names are checked.
    /// PascalCase variants like `<H1>` are assumed to be custom components and are ignored.
    /// :::
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```html,expect_diagnostic
    /// <h1></h1>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <h1>   </h1>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <h1 aria-hidden="true">content</h1>
    /// ```
    ///
    /// ```html,expect_diagnostic
    /// <h1><span aria-hidden="true">content</span></h1>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```html
    /// <h1>content</h1>
    /// ```
    ///
    /// ```html
    /// <h1><span>content</span></h1>
    /// ```
    ///
    /// ```html
    /// <h1><span aria-hidden="true"></span>content</h1>
    /// ```
    ///
    /// ```html
    /// <h1 aria-label="Section title"></h1>
    /// ```
    ///
    /// ## Accessibility guidelines
    ///
    /// - [WCAG 2.4.6](https://www.w3.org/TR/UNDERSTANDING-WCAG20/navigation-mechanisms-descriptive.html)
    ///
    pub UseHeadingContent {
        version: "next",
        name: "useHeadingContent",
        language: "html",
        sources: &[RuleSource::EslintJsxA11y("heading-has-content").same()],
        recommended: true,
        severity: Severity::Error,
    }
}

impl Rule for UseHeadingContent {
    type Query = Ast<AnyHtmlElement>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = UseHeadingContentOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();

        // Check if element is a heading tag (h1 - h6).
        // In HTML files, tag names are case-insensitive.
        // In component frameworks (Vue, Svelte, Astro), only lowercase is checked;
        // PascalCase variants are treated as custom components and ignored.
        let element_name = node.name()?;
        let source_type = ctx.source_type::<HtmlFileSource>();
        let is_html = source_type.is_html();
        if !is_heading_element(element_name.text(), is_html) {
            return None;
        }

        // `aria-hidden` on the heading itself takes priority over any accessible name.
        if get_truthy_aria_hidden_attribute(node).is_some() {
            return Some(());
        }

        // Headings with an accessible name via `aria-label`, `aria-labelledby` or `title`.
        if has_accessible_name(node) {
            return None;
        }

        // Self-closing headings (void-style) have no content.
        if node.as_html_element().is_none() {
            return Some(());
        }

        let html_element = node.as_html_element()?;
        // Skip analysis if we can't fully parse the element to avoid false positives.
        if html_element.opening_element().is_err() {
            return None;
        }

        // Check whether the heading has accessible content.
        if has_accessible_content(&html_element.children(), is_html) {
            return None;
        }

        // No accessible content found - emit diagnostic.
        Some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        let diagnostic = RuleDiagnostic::new(
            rule_category!(),
            node.syntax().text_trimmed_range(),
            markup! {
                "Provide screen reader accessible content when using heading elements."
            },
        )
        .note(markup! {
            "All headings on a page should have content that is accessible to screen readers."
        });

        Some(diagnostic)
    }
}

/// Returns `true` if `name` is a heading element (`h1`–`h6`).
///
/// In HTML files matching is case-insensitive; in component frameworks only
/// lowercase names are considered headings.
fn is_heading_element(name: &str, is_html: bool) -> bool {
    if is_html {
        matches!(
            name.to_ascii_lowercase().as_str(),
            "h1" | "h2" | "h3" | "h4" | "h5" | "h6"
        )
    } else {
        matches!(name, "h1" | "h2" | "h3" | "h4" | "h5" | "h6")
    }
}

/// Checks if `HtmlElementList` contains accessible content (non-empty text or visible elements).
fn has_accessible_content(html_child_list: &HtmlElementList, is_html: bool) -> bool {
    html_child_list.into_iter().any(|child| match &child {
        AnyHtmlElement::AnyHtmlContent(content) => is_accessible_text_content(content),
        AnyHtmlElement::HtmlElement(element) => {
            // Custom components (PascalCase) may render accessible content at runtime.
            if !is_html && starts_with_uppercase(element.tag_name().as_ref().map(|t| t.text())) {
                return true;
            }
            if html_element_has_truthy_aria_hidden(element) {
                false
            } else {
                has_accessible_content(&element.children(), is_html)
            }
        }
        AnyHtmlElement::HtmlSelfClosingElement(element) => {
            // Custom components (PascalCase) may render accessible content at runtime.
            if !is_html && starts_with_uppercase(element.tag_name().as_ref().map(|t| t.text())) {
                return true;
            }

            if html_self_closing_element_has_truthy_aria_hidden(element) {
                return false;
            }

            // In HTML, a self-closing `<img>` with a non-empty `alt` provides accessible content.
            if is_html && is_img_element(element) {
                return html_self_closing_element_has_non_empty_attribute(element, "alt");
            }

            false
        }
        AnyHtmlElement::HtmlBogusElement(_) | AnyHtmlElement::HtmlCdataSection(_) => true,
    })
}

/// Returns `true` if `name` starts with an uppercase ASCII letter.
fn starts_with_uppercase(name: Option<&str>) -> bool {
    name.is_some_and(|name| name.starts_with(|c: char| c.is_uppercase()))
}

