mod tmp_heading_check {
    use crate::analyze;
    use biome_analyze::{AnalysisFilter, AnalyzerOptions, ControlFlow, Never, RuleFilter};
    use biome_html_parser::parse_html;
    use biome_html_syntax::HtmlFileSource;
    use std::slice;

    fn count(source: &str, file_source: HtmlFileSource) -> usize {
        let parsed = parse_html(source, Default::default());
        let rule_filter = RuleFilter::Rule("a11y", "useHeadingContent");
        let options = AnalyzerOptions::default();
        let mut n = 0usize;
        analyze(
            &parsed.tree(),
            AnalysisFilter {
                enabled_rules: Some(slice::from_ref(&rule_filter)),
                ..AnalysisFilter::default()
            },
            &options,
            file_source,
            crate::HtmlAnalyzerServices::default(),
            |signal| {
                if let Some(diag) = signal.diagnostic() {
                    let msg = format!("{:?}", diag);
                    // ensure exact message text is present
                    assert!(
                        format!("{}", diag.message)
                            .contains("Provide screen reader accessible content when using heading elements."),
                        "unexpected message: {msg}"
                    );
                    n += 1;
                }
                ControlFlow::<Never>::Continue(())
            },
        );
        n
    }

    #[test]
    fn run_cases() {
        let html = HtmlFileSource::html();
        // Invalid
        assert_eq!(count("<h1></h1>", html), 1, "empty");
        assert_eq!(count("<h1>   </h1>", html), 1, "whitespace");
        assert_eq!(count("<h1 />", html), 1, "self-closing void");
        assert_eq!(count("<H1></H1>", html), 1, "uppercase HTML case-insensitive");
        assert_eq!(count(r#"<h1 aria-hidden="true">content</h1>"#, html), 1, "aria-hidden on heading");
        assert_eq!(count(r#"<h1 aria-hidden="true" aria-label="x">content</h1>"#, html), 1, "aria-hidden priority over aria-label");
        assert_eq!(count(r#"<h1><span aria-hidden="true">content</span></h1>"#, html), 1, "all children aria-hidden");
        assert_eq!(count(r#"<h6></h6>"#, html), 1, "h6 empty");

        // Valid
        assert_eq!(count("<h1>content</h1>", html), 0, "text content");
        assert_eq!(count("<h1><span>content</span></h1>", html), 0, "nested visible child");
        assert_eq!(count(r#"<h1><span aria-hidden="true"></span>content</h1>"#, html), 0, "mixed content");
        assert_eq!(count(r#"<h1 aria-label="Section title"></h1>"#, html), 0, "aria-label");
        assert_eq!(count(r#"<h1 aria-labelledby="x"></h1>"#, html), 0, "aria-labelledby");
        assert_eq!(count(r#"<h1 title="Home"></h1>"#, html), 0, "title");
        assert_eq!(count(r#"<h1><img alt="a descriptive text" /></h1>"#, html), 0, "img with alt");
        assert_eq!(count(r#"<h1><IMG alt="a descriptive text" /></h1>"#, html), 0, "IMG case-insensitive with alt");
        assert_eq!(count(r#"<h1><img alt="" /></h1>"#, html), 1, "img empty alt -> diagnostic");
        assert_eq!(count("<div></div>", html), 0, "non-heading ignored");

        // Vue/Svelte/Astro
        let vue = HtmlFileSource::vue();
        assert_eq!(count("<h1></h1>", vue), 1, "vue empty heading");
        assert_eq!(count("<H1></H1>", vue), 0, "vue uppercase custom component ignored");
        assert_eq!(count("<h1><Foo /></h1>", vue), 0, "vue self-closing custom component child");
        assert_eq!(count("<h1><Foo></Foo></h1>", vue), 0, "vue paired custom component child");
        assert_eq!(count("<h1><span></span></h1>", vue), 1, "vue empty lowercase child -> diagnostic");
    }
}
